import torch


def _linear_backward(input, grad_output, weight, output_mask):
    grad_input = grad_output @ weight if output_mask[0] else None
    grad_weight = grad_output.t() @ input if output_mask[1] else None
    grad_bias = grad_output.sum(dim=0) if output_mask[2] else None
    return grad_input, grad_weight, grad_bias


def run_correctness(input, grad_output, weight, output_mask):
    outputs = _linear_backward(
        input.float(), grad_output.float(), weight.float(), output_mask
    )
    grad_input, grad_weight, grad_bias = outputs
    return (
        grad_input.to(input.dtype) if grad_input is not None else None,
        grad_weight.to(weight.dtype) if grad_weight is not None else None,
        grad_bias.to(grad_output.dtype) if grad_bias is not None else None,
    )


def run(input, grad_output, weight, output_mask):
    return _linear_backward(input, grad_output, weight, output_mask)
